#!/usr/bin/env node
// Generated by mandao 0.1.0-beta.1 from .mandao/config.yml (scripts.runner). Do not edit: run `mandao sync`.
import { spawnSync } from 'node:child_process';
import { existsSync, readFileSync } from 'node:fs';
import { delimiter, dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const VERSION = "0.1.0-beta.1";
const RUNNER = "auto";
const BIN = process.platform === 'win32' ? ['mandao.cmd', 'mandao.exe', 'mandao'] : ['mandao'];
const SCRIPT_DIR = dirname(fileURLToPath(import.meta.url));

function lockedVersion() {
  try {
    const match = /^mandao:\s*['"]?([^\s'"]+)/m.exec(readFileSync(join(SCRIPT_DIR, '..', 'mandao.lock'), 'utf8'));
    return match?.[1] ?? VERSION;
  } catch {
    return VERSION;
  }
}

const PINNED = lockedVersion();

function reportedVersion(command) {
  const isNodeScript = /\.m?js$/.test(command);
  const result = spawnSync(isNodeScript ? process.execPath : command, isNodeScript ? [command, '--version'] : ['--version'], {
    encoding: 'utf8', shell: process.platform === 'win32', timeout: 10_000,
  });
  if (result.status !== 0) return undefined;
  return /\b(\d+\.\d+\.\d+(?:-[0-9A-Za-z.-]+)?)/.exec(result.stdout)?.[1];
}

function dogfoodBuild() {
  const root = resolve(SCRIPT_DIR, '../..');
  try {
    const pkg = JSON.parse(readFileSync(join(root, 'package.json'), 'utf8'));
    const build = join(root, 'dist', 'cli.js');
    return pkg.name === 'mandao' && existsSync(build) ? build : undefined;
  } catch {
    return undefined;
  }
}

function findLocal() {
  for (let dir = process.cwd(); ; dir = dirname(dir)) {
    for (const name of BIN) {
      const candidate = join(dir, 'node_modules', '.bin', name);
      if (existsSync(candidate)) return candidate;
    }
    if (dirname(dir) === dir) return undefined;
  }
}

function findGlobal() {
  for (const dir of (process.env.PATH ?? '').split(delimiter)) {
    if (!dir || dir.includes(join('node_modules', '.bin'))) continue;
    for (const name of BIN) {
      const candidate = join(dir, name);
      if (existsSync(candidate)) return candidate;
    }
  }
  return undefined;
}

const args = process.argv.slice(2);
const worktree = RUNNER === 'auto' || RUNNER === 'local' ? dogfoodBuild() : undefined;
const local = !worktree && (RUNNER === 'auto' || RUNNER === 'local') ? findLocal() : undefined;
const global = !worktree && !local && (RUNNER === 'auto' || RUNNER === 'global') ? findGlobal() : undefined;
const candidate = worktree ?? local ?? global;
const source = worktree ? 'worktree' : local ? 'local' : global ? 'global' : undefined;
const version = candidate ? reportedVersion(candidate) : undefined;
const mismatch = candidate && source !== 'worktree' && version !== PINNED ? { source, version: version ?? 'unknown' } : undefined;
const useNpx = !candidate || Boolean(mismatch);
const choice = useNpx
  ? RUNNER === 'auto' || RUNNER === 'npx'
    ? { source: 'npx', command: 'npx', args: ['-y', `mandao@${PINNED}`, ...args], mismatch }
    : undefined
  : {
      source,
      command: source === 'worktree' ? process.execPath : candidate,
      args: source === 'worktree' ? [candidate, ...args] : args,
      version,
    };

if (process.env.MANDAO_LAUNCHER_PRINT === '1') {
  console.log(JSON.stringify(choice ?? { source: 'none', runner: RUNNER }));
  process.exit(0);
}
if (!choice) {
  console.error(`mandao: no ${RUNNER} installation found (scripts.runner: ${RUNNER} in .mandao/config.yml)`);
  process.exit(127);
}
if (choice.mismatch)
  console.error(
    `mandao: ${choice.mismatch.source} install is ${choice.mismatch.version}; using locked mandao@${PINNED}`,
  );
const result = spawnSync(choice.command, choice.args, { stdio: 'inherit', shell: process.platform === 'win32' });
if (choice.mismatch && result.status !== 0)
  console.error(
    `mandao: if npm could not fetch the locked mandao@${PINNED} (for example after upgrading Mandao on purpose), pin the installed ${choice.mismatch.version} with: ${/\s/.test(candidate) ? JSON.stringify(candidate) : candidate} sync`,
  );
process.exit(result.status ?? 1);
